#include <bits/stdc++.h>
using namespace std;

const int inf = INT_MAX;

namespace mcmf {

const int N = 10001;
struct edge { int v, p; int c, w; };
vector<edge> g[N];
int vis[N], cur[N], n;
int dis[N], pot[N];

int addv(int c) {
    while (c--) g[n++].clear();
    return n - 1;
}

void adde(int u, int v, int c, int w) {
    g[u].push_back({ v, (int)g[v].size(), c, w });
    g[v].push_back({ u, (int)g[u].size() - 1, 0, -w });
}

bool dijkstra(int s, int t) {
    fill_n(dis, n, inf);
    fill_n(vis, n, 0);
    typedef pair<int, int> pli;
    priority_queue<pli, vector<pli>, greater<pli>> q;
    q.push({ dis[s] = 0, s });
    while (!q.empty()) {
        int u; int du; tie(du, u) = q.top(); q.pop();
        if (vis[u]) continue; vis[u] = 1;
        for (edge e : g[u]) {
            int v = e.v; int dv = du + pot[u] + e.w - pot[v];
            if (!e.c || vis[v] || dis[v] <= dv) continue;
            q.push({ dis[v] = dv, v });
        }
    }
    return vis[t];
}

bool dinic_bfs(int s, int t) {
    fill_n(vis, n, 0);
    queue<int> q; q.push(s); vis[s] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (edge e : g[u]) {
            int v = e.v;
            if (vis[v] || !e.c) continue;
            if (dis[v] != dis[u] + e.w - pot[v] + pot[u]) continue;
            vis[v] = vis[u] + 1; q.push(v);
        }
    }
    return vis[t] != 0;
}

int dinic_dfs(int u, int t, int f) {
    if (u == t)
        return f;
    int sf = 0;
    for (int& i = cur[u]; i != g[u].size(); ++i) {
        edge& e = g[u][i]; int v = e.v;
        if (!e.c || vis[v] != vis[u] + 1) continue;
        if (dis[v] != dis[u] + e.w - pot[v] + pot[u]) continue;
        int df = dinic_dfs(v, t, min(e.c, f));
        //if (df && u != 12 && v != 12 && u != 13 && v != 13) cout << u << ' ' << v << ' ' << df << ' ' << df * e.w << endl;
        sf += df; f -= df; e.c -= df; g[v][e.p].c += df;
        if (!f) break;
    }
    return sf;
}

pair<int, int> mincostflow(int s, int t, int mf) {
    int sf = 0, sc = 0;
    fill_n(pot, n, 0);
    while (dijkstra(s, t)) {
        int f = 0;
        while (dinic_bfs(s, t)) {
            fill_n(cur, n, 0);
            int df = dinic_dfs(s, t, mf);
            mf -= df; f += df;
            if (!mf) break;
        }
        sf += f; sc += (dis[t] + pot[t]) * f;
        for (int i = 0; i < n; ++i) pot[i] += dis[i];
        if (!mf) break;
    }
    return { sf, sc };
}

}

int main(void){
    int n, m, k, c, d;
    scanf("%d %d %d %d %d", &n, &m, &k, &c, &d);
    int l = max(n, k) * 2;
    mcmf::addv(l * n);
    int s = mcmf::addv(1), t = mcmf::addv(1);
    for (int j = 0; j < k; ++j) {
        int a; scanf("%d", &a);
        a--;
        mcmf::adde(s, a, 1, 0);
    }
    for (int z = 1; z <= m; ++z) {
        int u, v; scanf("%d %d", &u, &v);
        u--; v--;
        for (int i = 0; i + 1 < l; ++i) {
            int u1 = u + i * n, v1 = v + (i + 1) * n;
            int u2 = u + (i + 1) * n, v2 = v + i * n;
            for (int j = 0; j < k; ++j) {
                mcmf::adde(u1, v1, 1, c + d * (2 * j + 1));
                mcmf::adde(v2, u2, 1, c + d * (2 * j + 1));
            }
        }
    }
    for (int i = 0; i + 1 < l; ++i) {
        for (int j = 0; j < n; ++j) {
            int u = j + i * n, v = j + (i + 1) * n;
            mcmf::adde(u, v, inf, c);
        }
    }
    for (int i = 0; i < l; ++i)
        mcmf::adde(i * n, t, inf, 0);
    printf("%d\n", mcmf::mincostflow(s, t, inf).second);

    return 0;
}
